def _cn_kw_match(text, keywords):
    t = f" {text.lower()} "
    return any(kw in t for kw in keywords)

def cn_classify_tags(name_or_sku):
    """Product naam me keywords dekh ke Religious / Seasonal tag deta hai.
    Returns: {"religious": bool, "seasonal": bool}"""
    if not name_or_sku:
        return {"religious": False, "seasonal": False}
    t = str(name_or_sku)
    return {
        "religious": _cn_kw_match(t, CN_RELIGIOUS_KEYWORDS),
        "seasonal":  _cn_kw_match(t, CN_SEASONAL_KEYWORDS),
    }

_TYPE_CANON = {}
_TAXON_CANON = {}
_CUST_CANON = {}

def _canon(v, store, default, title=True):
    s = clean(v, default)
    k = re.sub(r"[^a-z0-9]", "", s.lower())
    if not k:
        return default
    if k not in store:
        store[k] = s.strip().title() if title else s.strip()
    return store[k]

def norm_type(v):  return _canon(v, _TYPE_CANON,  "Regular")

_TAXON_ALIASES = {
    "cufflink":  "Cufflinks",
    "cufflinks": "Cufflinks",
    "bangal":    "Bangle",
    "bangle":    "Bangle",
    "earring":   "Earrings",
    "earrings":  "Earrings",
    "eartop":    "Earrings",
    "eartops":   "Earrings",
}
def norm_taxon(v):
    s = clean(v, "General")
    k = re.sub(r"[^a-z0-9]", "", s.lower())
    if not k:
        return "General"
    if k in _TAXON_ALIASES:
        return _TAXON_ALIASES[k]
    return _canon(v, _TAXON_CANON, "General")

def norm_cust(v):  return _canon(v, _CUST_CANON,  "Unknown", title=False)

# Channel = Customer Name + Type se (user formula):
#  Customer me Myntra/Nykaa/AJIO/Tata/FNP/Fern/Mirraw/Amazon/Flipkart -> Ecom
#  Type: SOR->SOR, Website/Online->D2C, Purchase->B2B, Exhibition->Exhibition,
#  Bulk->Bulk, warna Type hi.
_ECOM_TOKENS = ("myntra", "nykaa", "ajio", "tata", "fnp", "fern",
                "mirraw", "amazon", "flipkart")
def calc_channel(customer, typ):
    c = str(customer or "").lower()
    if any(tok in c for tok in _ECOM_TOKENS):
        return "Ecom"
    t = str(typ or "").strip().lower()
    if t == "sor":        return "SOR"
    if t == "website":    return "D2C"
    if t == "online":     return "D2C"
    if t == "purchase":   return "B2B"
    if t == "exhibition": return "Exhibition"
    if t == "bulk":       return "Bulk"
    return str(typ or "").strip() or "Other"

# Sub-channel = Ecom ke andar KAUNSA marketplace (Myntra/Nykaa/AJIO/Amazon/
# Flipkart/Tata). D2C/SOR/B2B ke liye abhi granular source data (Meta/Google/
# Organic) available nahi hai — Type hi sub-channel ban jata hai.
_MARKETPLACE_MAP = [
    ("myntra", "Myntra"), ("nykaa", "Nykaa"), ("ajio", "AJIO"),
    ("tata", "Tata CLiQ"), ("fnp", "FNP"), ("fern", "Fern"),
    ("mirraw", "Mirraw"), ("amazon", "Amazon"), ("flipkart", "Flipkart"),
]
def calc_sub_channel(customer, channel, typ):
    if channel == "Ecom":
        c = str(customer or "").lower()
        for tok, label in _MARKETPLACE_MAP:
            if tok in c:
                return label
        return "Other Marketplace"
    return channel  # D2C/SOR/B2B/Exhibition/Bulk: sub-channel = channel hi

def find_col(cols, *cands):
    norm = {re.sub(r"[^a-z0-9]","", str(c).lower()): c for c in cols}
    for cand in cands:
        k = re.sub(r"[^a-z0-9]","", cand.lower())
        if k in norm: return norm[k]
    for cand in cands:
        k = re.sub(r"[^a-z0-9]","", cand.lower())
        for nk, orig in norm.items():
            if k and k in nk: return orig
    return None

def classify_status(item, current_month_key=""):
    # Koi dispatch hi nahi hui (COSA me record nahi) → "No Record"
    if item["dispatch_count"] == 0:
        return "No Record"
    # "New Launch" = sirf wahi jo IS MAHINE launch hua (launch date se).
    if current_month_key and item.get("launch_key") == current_month_key:
        return "New Launch"
    total_inv = item["inv_stock"] + item["inv_wip"]
    if total_inv >= 20 and item["qty_6m"] == 0: return "Slow Movers"
    return "Good Running"


# ════════════════════════════════════════════════════════════════
# 🚨 SMART ALERTS + BEST CHANNEL — har product ke liye
#   - High Sale / Low Stock (stockout risk)
#   - High Stock / Low Sale (overstock, slow mover)
#   - Dormant 30d / 90d (active product par recent koi sale nahi)
#   - Sudden Sales Drop (last 30d vs previous 30d)
#   - Best Channel (jis channel par sabse zyada revenue aaya)
# ════════════════════════════════════════════════════════════════
def _compute_alerts_and_channel(item, today):
    if isinstance(today, datetime):
        today = today.date()
    flags = []
    stock = item.get("inv_stock") or 0
    wip = item.get("inv_wip") or 0
    total_avail = stock + wip
    q30 = item.get("qty_1m") or 0
    q90 = item.get("qty_3m") or 0
    q6m = item.get("qty_6m") or 0
    dispatch_count = item.get("dispatch_count") or 0
    last_dt_s = item.get("last_dispatch_date") or "N/A"

    # --- High Sale + Low Stock (stockout risk) ---
    # 30-din me achhi bikri (>=5 units) par available stock+wip usse kam
    if q30 >= 5 and total_avail < q30:
        flags.append({"code": "low_stock_high_sale", "label": "⚠️ High Sale, Low Stock",
                       "detail": f"30D sale {int(q30)} units, but only {int(total_avail)} available (stock+WIP)."})

    # --- High Stock + Low Sale (overstock / slow mover) ---
    if total_avail >= 20 and q90 <= 1:
        flags.append({"code": "high_stock_low_sale", "label": "📦 High Stock, Low Sale",
                       "detail": f"{int(total_avail)} units available (stock+WIP), only {int(q90)} sold in last 90 days."})

    # --- Dormant: active product (has stock) but zero sale in 30/90 days ---
    days_since_last = None
    if last_dt_s and last_dt_s != "N/A":
        try:
            days_since_last = (today - datetime.strptime(last_dt_s, "%Y-%m-%d").date()).days
        except Exception:
            days_since_last = None
    if dispatch_count > 0 and total_avail > 0:
        if q90 == 0 and (days_since_last is None or days_since_last >= 90):
            flags.append({"code": "dormant_90d", "label": "💤 Zero Sale (90+ days)",
                           "detail": f"No sale in last 90 days despite {int(total_avail)} units available."})
        elif q30 == 0 and (days_since_last is None or days_since_last >= 30):
            flags.append({"code": "dormant_30d", "label": "💤 Zero Sale (30+ days)",
                           "detail": f"No sale in last 30 days despite {int(total_avail)} units available."})

    # --- OOS (Out of Stock) — koi stock/WIP nahi ---
    if total_avail <= 0:
        flags.append({"code": "oos", "label": "🔴 Currently OOS",
                       "detail": "Inventory stock and WIP are both 0 — replenishment required."})
    elif total_avail > 0 and item.get("reorder_qty", 0) > 0 and q30 >= 3:
        flags.append({"code": "replenish_soon", "label": "🟠 Replenish Soon",
                       "detail": f"Stock+WIP {int(total_avail)} units, expected demand exceeds this — reorder {int(item.get('reorder_qty',0))} units."})

    # --- Growing / Declining trend: last 30d rate vs prior 90d avg rate ---
    q90_rate30 = (q90 / 3.0) if q90 else 0.0     # per-30d average over last 90 days
    trend = None
    if q90_rate30 >= 2 or q30 >= 2:
        if q90_rate30 > 0:
            change_pct = round(((q30 - q90_rate30) / q90_rate30) * 100)
        else:
            change_pct = 100 if q30 > 0 else 0
        if change_pct >= 20:
            trend = "growing"
            flags.append({"code": "growing", "label": f"📈 Growing (+{change_pct}%)",
                           "detail": f"Last 30D sale {int(q30)} vs {round(q90_rate30,1)} avg/30D over last 90 days."})
        elif change_pct <= -20:
            trend = "declining"
            flags.append({"code": "declining", "label": f"📉 Declining ({change_pct}%)",
                           "detail": f"Last 30D sale {int(q30)} vs {round(q90_rate30,1)} avg/30D over last 90 days."})

    # --- Sudden Sales Drop: last 30d vs prior 30d (30-60 days ago) ---
    ents = item.get("sales_entries") or []
    prior_30_60 = 0.0
    for e in ents:
        ds = e.get("date")
        if not ds or ds == "N/A":
            continue
        try:
            d = datetime.strptime(ds, "%Y-%m-%d").date()
        except Exception:
            continue
        delta = (today - d).days
        if 30 < delta <= 60:
            prior_30_60 += float(e.get("qty") or 0)
    if prior_30_60 >= 5 and q30 <= prior_30_60 * 0.4:
        drop_pct = round((1 - (q30 / prior_30_60)) * 100) if prior_30_60 else 0
        flags.append({"code": "sales_drop", "label": f"📉 Sudden Sales Drop ({drop_pct}%)",
                       "detail": f"Sold {int(prior_30_60)} units in the previous 30 days, only {int(q30)} in the last 30 days."})

    # --- Best Channel (highest revenue channel for this SKU) ---
    chan_rev = {}
    chan_qty = {}
    sub_rev = {}   # marketplace-level (sub_channel) breakdown — sirf Ecom rows
    for e in ents:
        ch = e.get("channel") or "Other"
        chan_rev[ch] = chan_rev.get(ch, 0.0) + float(e.get("rev") or 0)
        chan_qty[ch] = chan_qty.get(ch, 0.0) + float(e.get("qty") or 0)
        if ch == "Ecom":
            sch = e.get("sub_channel") or "Other Marketplace"
            sub_rev[sch] = sub_rev.get(sch, 0.0) + float(e.get("rev") or 0)
    best_channel = ""
    best_channel_rev = 0.0
    if chan_rev:
        best_channel = max(chan_rev, key=chan_rev.get)
        best_channel_rev = chan_rev[best_channel]
    best_marketplace = ""
    best_marketplace_rev = 0.0
    if sub_rev:
        best_marketplace = max(sub_rev, key=sub_rev.get)
        best_marketplace_rev = sub_rev[best_marketplace]

    return flags, best_channel, best_channel_rev, days_since_last, best_marketplace, best_marketplace_rev, trend


def simple_forecast(entries, days_ahead=30):
    """Expected DEMAND (units) in the next `days_ahead` days.

    Criteria (velocity-based, recent-weighted):
      • Recent rate (last 60 din) ko 70% weight, lambe rate (last 180 din) ko
        30% weight — taaki recent maang zyada bole par purana bhi count ho.
      • Agar recent data nahi to overall avg daily rate.
      • Trend (OLS slope) thoda upar/niche adjust karta hai (max ±25%).
    Yeh "next 30 days me kitna bikega" batata hai (reorder iske upar banta hai).
    """
    if not entries:
        return 0
    dated = [(e["date"], e["qty"]) for e in entries if e.get("date") and e["date"] != "N/A"]
    if not dated:
        return 0
    today = now_ist().date()
    def _d(iso):
        try: return date(int(iso[0:4]), int(iso[5:7]), int(iso[8:10]))
        except Exception: return None

    q60 = q180 = q_all = 0.0
    first = None
    for iso, qty in dated:
        dd = _d(iso)
        if dd is None:
            continue
        age = (today - dd).days
        if age < 0:
            age = 0
        q_all += qty
        if age <= 60:  q60  += qty
        if age <= 180: q180 += qty
        if first is None or dd < first:
            first = dd

    rate60  = q60  / 60.0
    rate180 = q180 / 180.0
    # blended daily rate (recent weighted)
    if q60 > 0 or q180 > 0:
        daily = 0.70 * rate60 + 0.30 * rate180
    else:
        span_days = max(1, (today - first).days) if first else 1
        daily = q_all / span_days

    base = daily * days_ahead

    # Halka trend nudge (max ±25%): weekly OLS slope ka sign/strength.
    from collections import defaultdict
    weekly = defaultdict(float)
    ref_ord = date(2020, 1, 1).toordinal()
    for iso, qty in dated:
        dd = _d(iso)
        if dd is None:
            continue
        weekly[(dd.toordinal() - ref_ord) // 7] += qty
    if len(weekly) >= 3:
        xs = np.array(sorted(weekly.keys()), dtype=float)
        ys = np.array([weekly[x] for x in xs], dtype=float)
        xm, ym = xs.mean(), ys.mean()
        slope = np.sum((xs - xm) * (ys - ym)) / (np.sum((xs - xm) ** 2) + 1e-9)
        if ym > 0:
            nudge = max(-0.25, min(0.25, (slope / ym)))
            base *= (1.0 + nudge)

    return max(0, int(round(base)))


# ── Data Engine ──────────────────────────────────────────────
def _fetch_csv_fresh(url):
    """Google published-CSV ko Google ~5 min CDN-cache karta hai — cache-buster
    param + no-cache headers se hamesha LATEST data milta hai."""
    bust = ("&" if "?" in url else "?") + f"cachebust={int(time.time()*1000)}"
    headers = {"Cache-Control": "no-cache, no-store, max-age=0",
               "Pragma": "no-cache",
               "User-Agent": "Mozilla/5.0 (CosaNostraaDashboard)"}
    last_err = None
    for attempt in range(3):
        try:
            r = requests.get(url + bust, headers=headers, timeout=45, allow_redirects=True)
            r.raise_for_status()
            txt = r.content.decode("utf-8", errors="replace")
            if "<html" in txt[:200].lower():
                raise ValueError("Received HTML instead of CSV — re-check the sheet's Publish-to-web setting")
            return pd.read_csv(io.StringIO(txt), dtype=str, on_bad_lines="skip")
        except Exception as e:
            last_err = e
            time.sleep(2)
    raise last_err

_DATA_LOCK = threading.Lock()
_DF_REFS = {}

def _df_chunks(df, size=4000):
    """DataFrame ko chhote-chhote dict-chunks mein iterate karo —
    poora .to_dict('records') ek saath banane se RAM double ho rahi thi."""
    n = len(df)
    for start in range(0, n, size):
        for rec in df.iloc[start:start + size].to_dict("records"):
            yield rec

_WARMUP = {"stage": "idle", "detail": "", "done": 0, "total": 0}

def _wstage(stage, detail="", done=0, total=0):
    _WARMUP.update({"stage": stage, "detail": detail, "done": done, "total": total})

def _malloc_trim():
    """Linux par Python freed memory ko hamesha OS ko wapas nahi karta —
    glibc malloc_trim se RSS actually neeche aata hai (512MB tier ke liye zaroori)."""
    try:
        import ctypes
        ctypes.CDLL("libc.so.6").malloc_trim(0)
    except Exception:
        pass

def _free_dataframes():
    """Raw pandas frames ko refresh ke turant baad free karo (100MB+ bachat)."""
    try:
        _DF_REFS.clear()
        _gc.collect()
        _malloc_trim()
    except Exception:
        pass

def get_data(force=False):
    global CACHE
    if not force and CACHE["data"] and (time.time() - CACHE["ts"] < CACHE_TTL):
        return CACHE["data"]
    # multi-device: ek hi waqt par ek hi refresh chale, baaki cached serve karein
    if not _DATA_LOCK.acquire(blocking=False):
        with _DATA_LOCK:
            pass
        if CACHE["data"]:
            return CACHE["data"]
        _DATA_LOCK.acquire()
    try:
        # Purana data ko None mat karo jab tak naya ready na ho — warna refresh
        # ke beech /api/data ko data None milta tha aur site reload-loop me ja
        # rahi thi. _refresh_data() khud CACHE ko atomically set karta hai.
        _prev = CACHE.get("data")
        try:
            result = _refresh_data()
        except Exception:
            CACHE["data"] = _prev      # fail ho to purana wapas
            raise
        finally:
            _prev = None
        _gc.collect()
        _free_dataframes()
        return result
    finally:
        _DATA_LOCK.release()

def _refresh_data():
    global CACHE
    dbg = {"errors": []}
    try:
        _wstage("fetching", "Downloading inventory sheet…")
        inv   = _fetch_csv_fresh(INV_URL)
        _wstage("fetching", "Downloading sales sheet (54k rows)…")
        cosa = _fetch_csv_fresh(COSA_URL)
        _DF_REFS["inv"] = inv; _DF_REFS["cosa"] = cosa
        inv.columns   = [str(c).strip() for c in inv.columns]
        cosa.columns = [str(c).strip() for c in cosa.columns]
    except Exception as e:
        dbg["errors"].append(f"load: {e}")
        CACHE["debug"] = dbg
        return [], [], [], [], [], [], [], "", "", "", "", "", 0.0, 0.0, {"total":0,"yesterday":0,"this_month":0,"this_fy":0,"prev_fy":0}

    dbg["inv_cols"]   = list(inv.columns)
    dbg["cosa_cols"] = list(cosa.columns)

    # ── Inventory columns ────────────────────────────────────
    I_SKU = find_col(inv.columns, "SKU") or inv.columns[0]
    I_IMG = find_col(inv.columns, "Image Link","imagelink") or find_col(inv.columns,"image","img")
    I_MRP  = find_col(inv.columns, "MRP", "mrp", "m.r.p")
    I_COST = find_col(inv.columns, "Cost", "cost", "product cost", "hi cost", "item cost") \
             or (inv.columns[12] if len(inv.columns) > 12 else None)   # fallback → M column
    I_TAX = find_col(inv.columns, "Taxon","category","collection")
    I_PLT = find_col(inv.columns, "Plating","finish","metal")
    I_DIM = find_col(inv.columns, "Product Dimensions","Dimensions","Dimension","Size")
    I_LNCH = find_col(inv.columns, "Launch Date","Launching Date","Launch","Launched")
    I_STONE = find_col(inv.columns, "Stone Details","Stone Detail","Remarks","Remark","combo","combo sku","combo skus","combo_skus","stone")
    I_COMBO_DETAILS = find_col(inv.columns, "Combo Details","Combo Detail","Set Details","Set Detail","Combo")
    I_STONE_COLOR = find_col(inv.columns, "Stone Color","stone colour","stonecolor")
    I_PACK  = find_col(inv.columns, "Pack Details","Pack Detail","Packing Details","Packing","Pack")
    stk_cands = [c for c in inv.columns if "inv" in c.lower() and "stock" in c.lower()
                 and "3p" not in c.lower() and "web" not in c.lower() and "myntr" not in c.lower()]
    I_STK = stk_cands[0] if stk_cands else find_col(inv.columns,"Inv. Stock","stock")
    stk_3p_cands = [c for c in inv.columns if "inv" in c.lower() and "stock" in c.lower()
                    and "3p" in c.lower()]
    I_STK_3P = stk_3p_cands[0] if stk_3p_cands else find_col(inv.columns,"Inv. Stock _3P","Inv Stock _3P","stock 3p","3p stock")
    wip_exact = [c for c in inv.columns if re.sub(r"[^a-z0-9]","",c.lower()) == "invwip"]
    if wip_exact:
        I_WIP = wip_exact[0]
    else:
        wip_cands = [c for c in inv.columns if "wip" in c.lower()
                     and "website" not in c.lower() and "designer" not in c.lower()
                     and "customer" not in c.lower() and "sor" not in c.lower()]
        I_WIP = wip_cands[0] if wip_cands else find_col(inv.columns,"Inv (WIP)","wip")

    # Exact WH+WIP value from the All Product inventory sheet (column AB).
    # Header-match is preferred; AB is retained as a safe fallback because the
    # sheet occasionally changes punctuation/spacing in the heading.
    I_WH_WIP = find_col(
        inv.columns, "WH+WIP", "WH + WIP", "WH WIP",
        "Warehouse+WIP", "Warehouse + WIP", "Warehouse WIP"
    )
    if I_WH_WIP is None and len(inv.columns) > 27:
        I_WH_WIP = inv.columns[27]  # AB

    # Channel-specific WIP columns
    def _find_wip_col(keywords):
        for c in inv.columns:
            cl = c.lower()
            if "wip" in cl and all(k in cl for k in keywords):
                return c
        return None

    I_WIP_WEBSITE  = _find_wip_col(["website"]) or find_col(inv.columns,"WIP (Website Repeat)","wip website","website wip")
    I_WIP_DESIGNER = _find_wip_col(["designer"]) or find_col(inv.columns,"WIP (Designer)","wip designer","designer wip")
    I_WIP_CUSTOMER = _find_wip_col(["customer"]) or find_col(inv.columns,"WIP (Customer)","wip customer","customer wip")
    # SOR WIP — some sheets may have a dedicated SOR WIP column; fallback to None
    I_WIP_SOR = _find_wip_col(["sor"]) or find_col(inv.columns,"WIP (SOR)","wip sor","sor wip")

    # Blocked Qty (column U = index 20). Naam pehle, warna position.
    _inv_cols = list(inv.columns)
    def _inv_at(i): return _inv_cols[i] if len(_inv_cols) > i else None
    I_BLOCKED = (find_col(inv.columns, "Blocked Qty", "blocked qty", "blocked", "block qty")
                 or _inv_at(20))

    # ── COSA columns ────────────────────────────────────────
    cols = list(cosa.columns)
    def _at(idx): return cols[idx] if len(cols) > idx else None

    C_DATE  = _at(0)  or find_col(cosa.columns, "Dispatch Date","date")
    # Main COSA source stays dispatch-date based. Rakhi transactions are loaded
    # separately from the dedicated cossa_orderdate sheet after this frame is
    # processed, so no Rakhi metric can silently fall back to Dispatch Date.
    C_ODATE = find_col(
        cosa.columns,
        "cossa_orderdate", "cosa_orderdate", "Cossa Order Date", "COSA Order Date",
        "Order Date", "order date", "orderdate"
    )
    C_FY    = _at(1)  or find_col(cosa.columns, "FY Year","fy","financial year")
    C_SKU   = _at(2)  or find_col(cosa.columns, "SKU","item code") or cols[0]
    # G (index 6) = Final Qty (confirmed layout). Header-match pehle "Final Qty"
    # par exact, warna column G. (Sirf "qty" match karne se "Total Qty"=E pakad
    # leta tha — isliye exact "Final Qty" + fixed index G hi bharosemand hai.)
    C_QTY   = (find_col(cosa.columns, "Final Qty","final quantity","final_qty")
               or _at(6) or find_col(cosa.columns, "qty","quantity") or _at(5))
    # F = Return Qty (index 5)
    C_RET   = find_col(cosa.columns, "Return Qty","return qty","returns","returned qty") or _at(5)
    # H = Selling Price (per-unit SP recorded in COSA), I = Net Revenue
    C_SP    = find_col(cosa.columns, "Selling Price","selling price","sp","unit price") or _at(7)
    C_REV   = _at(8)  or find_col(cosa.columns, "Net Revenue","net rev","revenue")
    C_CUST  = _at(9)  or find_col(cosa.columns, "Customer Name","customer","client","party")
    C_TYPE  = _at(10) or find_col(cosa.columns, "Type","channel","mode")

    dbg["resolved"] = {
        "inv":   {"sku":I_SKU,"stock":I_STK,"wip":I_WIP,"wh_wip":I_WH_WIP,"mrp":I_MRP,"img":I_IMG,"tax":I_TAX,"plt":I_PLT,"combo":I_STONE},
        "cosa": {"sku":C_SKU,"qty":C_QTY,"revenue":C_REV,"date":C_DATE,"fy":C_FY,"cust":C_CUST,"type":C_TYPE},
    }

    # Extract all valid known Inventory SKUs for fuzzy matching fallback
    _wstage("processing", "Indexing inventory SKUs…")
    inv_skus_map = {}
    for r in _df_chunks(inv):
        raw_inv = clean(r.get(I_SKU,"")) if I_SKU else ""
        if raw_inv:
            # Map normalized alphanumeric string to standard uppercase SKU
            n_key = re.sub(r'[^A-Z0-9]', '', raw_inv.upper())
            if n_key not in inv_skus_map:
                inv_skus_map[n_key] = raw_inv.upper()

    # ── Website repeat-customer identity index ─────────────────────────
    # Billing Address Name + Final Billing Address together identify one
    # Website customer. Multiple order-lines/orders for the same customer
    # on the same date are collapsed into one customer-session. Only a short
    # SHA-1 token is sent to the browser; names/addresses themselves are not.
    website_customer_events = {}
    website_city_events = {}
    website_payment_events = {}
    website_payment_summary = {"cod": 0, "prepaid": 0, "total": 0, "daily": []}
    try:
        _wstage("fetching", "Downloading Website customer sheet for repeat-rate…")
        web_orders = _fetch_csv_fresh(RAKHI_WEBSITE_ADDR_URL)
        _DF_REFS["website_repeat"] = web_orders
        web_orders.columns = [str(c).strip() for c in web_orders.columns]
        wcols = list(web_orders.columns)
        def _wat(i): return wcols[i] if len(wcols) > i else None

        W_DATE = (find_col(web_orders.columns, "Dispatch Date", "Display Order Date",
                           "Order Date", "order date", "date") or _wat(1))
        W_NAME = (find_col(web_orders.columns, "Billing Address Name",
                           "Billing Name", "Customer Name", "customer name") or _wat(3))
        W_ADDR = (find_col(web_orders.columns, "Final Billing Address",
                           "Billing Address", "final address", "address") or _wat(4))
        W_SKU = (find_col(web_orders.columns, "New SKU", "SKU", "sku code",
                          "product sku", "item sku") or _wat(7))
        _website_qty_keys = {
            "finalqty", "finalquantity", "soldqty", "saleqty",
            "orderqty", "orderedqty", "totalqty", "quantity", "qty"
        }
        W_QTY = next((
            c for c in web_orders.columns
            if re.sub(r"[^a-z0-9]", "", str(c).lower()) in _website_qty_keys
        ), None)
        W_REV = find_col(
            web_orders.columns,
            "Net Revenue", "Final Revenue", "Order Revenue", "Line Revenue",
            "Order Value", "Line Amount", "Total Amount", "Amount"
        )
        W_SP = find_col(
            web_orders.columns,
            "Selling Price", "Sale Price", "Unit Selling Price", "Unit Price", "SP"
        )
        W_STATUS = find_col(web_orders.columns, "Sale Order Status", "Order Status", "status")
        # Website sheet: M column stores payment mode (0=Prepaid, 1=COD).
        # Header match is preferred; fixed M-column fallback protects against
        # harmless header spelling/spacing changes in the source sheet.
        W_COD = find_col(web_orders.columns, "COD", "Cash On Delivery", "Cash on Delivery") or _wat(12)
        W_ORDER = find_col(
            web_orders.columns,
            "Shipping Package Code", "Invoice Code", "Order ID", "Order Code",
            "Order Number", "Sale Order Code"
        ) or _wat(8)

        dbg["website_repeat_cols"] = wcols
        dbg["website_repeat_resolved"] = {
            "date": W_DATE, "name": W_NAME, "address": W_ADDR,
            "sku": W_SKU, "qty": W_QTY, "revenue": W_REV,
            "selling_price": W_SP, "status": W_STATUS,
            "cod": W_COD, "order": W_ORDER,
        }

        # Repeat-rate sessions and Website/D2C city sales are built from the
        # same Website order source. City rows are compacted by SKU + date +
        # city so the browser can recalculate the top city for active date
        # filters without sending customer names or full addresses.
        _web_event_sets = {}
        _web_city_sums = {}
        _web_payment_sets = {}
        _web_all_payment_orders = {}
        if W_DATE and W_NAME and W_ADDR and W_SKU:
            for web_row_no, r in enumerate(_df_chunks(web_orders)):
                status = str(r.get(W_STATUS, "") or "").strip().lower() if W_STATUS else ""
                if status and any(x in status for x in ("cancel", "void", "failed")):
                    continue
                dt_web = parse_date_any(r.get(W_DATE, ""))
                if dt_web is None:
                    continue
                date_iso = dt_web.strftime("%Y-%m-%d")
                raw_web_sku = clean(r.get(W_SKU, ""))
                if not raw_web_sku:
                    continue
                n_web = re.sub(r"[^A-Z0-9]", "", raw_web_sku.upper())
                mapped_web_sku = inv_skus_map.get(n_web, raw_web_sku.upper())

                raw_name = str(r.get(W_NAME, "") or "").strip()
                raw_addr = str(r.get(W_ADDR, "") or "").strip()

                # If an explicit Qty column exists, zero/negative rows are not
                # sales (often returns/adjustments) and must not affect city or
                # repeat metrics. Without a Qty column, one order-line = one unit.
                qty_web = to_num(r.get(W_QTY, 0)) if W_QTY else 1.0
                if W_QTY and qty_web <= 0:
                    continue
                if not W_QTY:
                    qty_web = 1.0

                # Payment mix is order-based, not line-based. All Website SKUs
                # feed the compact Home daily summary; RKH/CMB events are also
                # retained per SKU for the Rakhi tab.
                if W_COD:
                    raw_cod = str(r.get(W_COD, "") or "").strip().casefold()
                    cod_value = None
                    if raw_cod in ("1", "1.0", "cod", "cash on delivery", "cash-on-delivery", "true", "yes"):
                        cod_value = 1
                    elif raw_cod in ("0", "0.0", "prepaid", "pre-paid", "false", "no"):
                        cod_value = 0
                    if cod_value is not None:
                        raw_order = clean(r.get(W_ORDER, "")) if W_ORDER else ""
                        if not raw_order:
                            raw_order = f"ROW:{date_iso}:{mapped_web_sku}:{web_row_no}"
                        order_token = hashlib.sha1(
                            raw_order.casefold().encode("utf-8", errors="ignore")
                        ).hexdigest()[:16]
                        payment_event = {
                            "o": _si(order_token), "p": int(cod_value), "d": _si(date_iso)
                        }
                        _web_all_payment_orders[order_token] = payment_event
                        if re.match(r"^(RKH|CMB)", str(mapped_web_sku or "").strip(), re.I):
                            _web_payment_sets.setdefault(mapped_web_sku, {})[order_token] = payment_event

                # PIN is the State source of truth. City is validated against
                # it, and State is kept in the compact event so same-named
                # cities in different States never get merged.
                city_web, pin_web = _extract_city_pin_from_address(raw_addr)
                state_web = _pincode_to_state(pin_web) if pin_web else ""
                if state_web:
                    city_web = _normalize_city_for_state(city_web, state_web, pin_web)
                if city_web:
                    rev_web = to_num(r.get(W_REV, 0)) if W_REV else 0.0
                    if rev_web <= 0 and W_SP:
                        unit_sp_web = to_num(r.get(W_SP, 0))
                        if unit_sp_web > 0:
                            rev_web = float(unit_sp_web) * float(qty_web)
                    city_key = (date_iso, state_web, city_web)
                    sku_city_map = _web_city_sums.setdefault(mapped_web_sku, {})
                    city_bucket = sku_city_map.setdefault(city_key, {"q": 0.0, "r": 0.0})
                    city_bucket["q"] += float(qty_web)
                    city_bucket["r"] += float(rev_web)

                name_norm = re.sub(r"[^a-z0-9]+", " ", raw_name.casefold()).strip()
                addr_norm = re.sub(r"[^a-z0-9]+", " ", raw_addr.casefold()).strip()
                if not name_norm or not addr_norm:
                    continue
                identity = name_norm + "|" + addr_norm
                customer_token = hashlib.sha1(identity.encode("utf-8", errors="ignore")).hexdigest()[:16]
                event_key = (customer_token, date_iso)
                _web_event_sets.setdefault(mapped_web_sku, {})[event_key] = {
                    "c": _si(customer_token), "d": _si(date_iso),
                    "s": _si(customer_token + "|" + date_iso),
                }

        website_customer_events = {
            sku: sorted(events.values(), key=lambda x: (x["d"], x["c"]))
            for sku, events in _web_event_sets.items()
        }
        website_city_events = {
            sku: [
                {
                    "d": _si(day), "s": _si(state), "c": _si(city),
                    "q": round(float(vals.get("q", 0.0)), 4),
                    "r": round(float(vals.get("r", 0.0)), 2),
                }
                for (day, state, city), vals in sorted(
                    city_map.items(), key=lambda x: (x[0][0], x[0][1], x[0][2])
                )
            ]
            for sku, city_map in _web_city_sums.items()
        }
        website_payment_events = {
            sku: sorted(events.values(), key=lambda x: (x["d"], x["o"]))
            for sku, events in _web_payment_sets.items()
        }
        _payment_daily = {}
        _all_cod = _all_prepaid = 0
        for payment_event in _web_all_payment_orders.values():
            day = payment_event.get("d", "")
            payment = int(payment_event.get("p", 0))
            bucket = _payment_daily.setdefault(day, {"d": _si(day), "cod": 0, "prepaid": 0})
            if payment == 1:
                bucket["cod"] += 1
                _all_cod += 1
            else:
                bucket["prepaid"] += 1
                _all_prepaid += 1
        website_payment_summary = {
            "cod": _all_cod,
            "prepaid": _all_prepaid,
            "total": _all_cod + _all_prepaid,
            "daily": [_payment_daily[d] for d in sorted(_payment_daily)],
        }
        dbg["website_repeat_skus"] = len(website_customer_events)
        dbg["website_repeat_sessions"] = sum(len(v) for v in website_customer_events.values())
        dbg["website_city_skus"] = len(website_city_events)
        dbg["website_city_buckets"] = sum(len(v) for v in website_city_events.values())
        dbg["website_payment_skus"] = len(website_payment_events)
        dbg["website_payment_orders"] = sum(len(v) for v in website_payment_events.values())
        dbg["website_all_payment_orders"] = website_payment_summary["total"]
    except Exception as e:
        dbg["errors"].append(f"website repeat/city: {e}")
        website_customer_events = {}
        website_city_events = {}
        website_payment_events = {}
        website_payment_summary = {"cod": 0, "prepaid": 0, "total": 0, "daily": []}
    finally:
        try:
            del web_orders
        except Exception:
            pass
        _DF_REFS.pop("website_repeat", None)
        _gc.collect()

    sales_exact = {}
    custs, types_, fyears = set(), set(), set()
    channels_ = set()
    sub_channels_ = set()
    _TYPE_CANON.clear(); _TAXON_CANON.clear(); _CUST_CANON.clear()

    # Unified Grand Totals logic: Everything aggregates line-by-line
    grand_net_revenue = 0.0
    grand_final_qty   = 0.0
    kpi_yesterday = kpi_month = kpi_fy = kpi_prev_fy = 0.0

    today_dt = now_ist().replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=None)
    yest_dt  = today_dt - timedelta(days=1)
    cm_start = today_dt.replace(day=1)
    fy_label_cur, fy_start_cur, fy_end_cur = fy_bounds(now_ist())
    fy_label_prev = prev_fy_label(fy_label_cur)
    fy_start_cur_n = fy_start_cur.replace(tzinfo=None)
    fy_end_cur_n   = fy_end_cur.replace(tzinfo=None)

    # ── Last full month vs SAME month last year (month-on-month YoY) ──
    lm_end   = cm_start - timedelta(days=1)        # last day of previous month
    lm_start = lm_end.replace(day=1)               # first day of previous month
    lm_key   = lm_start.strftime("%Y-%m")
    lm_label = lm_start.strftime("%b %Y")
    ly_start = lm_start.replace(year=lm_start.year - 1)
    ly_key   = ly_start.strftime("%Y-%m")
    ly_label = ly_start.strftime("%b %Y")
    kpi_last_month = kpi_last_year_month = 0.0

    _fuzzy_cache = {}
    # SPEED: prefix buckets — fuzzy sirf same-prefix SKUs par chale (10k -> ~50 candidates)
    _prefix_buckets = {}
    for _k in inv_skus_map.keys():
        _prefix_buckets.setdefault(_k[:4], []).append(_k)
    _n_rows = len(cosa)
    for _ri, r in enumerate(_df_chunks(cosa)):
        if (_ri % 2500) == 0:
            _wstage("processing", "Matching sales records…", _ri, _n_rows)
        qty = to_num(r.get(C_QTY, 0)) if C_QTY else 0.0
        rev = to_num(r.get(C_REV, 0)) if C_REV else 0.0
        sp  = to_num(r.get(C_SP, 0))  if C_SP  else 0.0   # per-unit Selling Price (COSA col H)
        ret = to_num(r.get(C_RET, 0)) if C_RET else 0.0   # Return Qty (COSA col F)

        # SANITY: ek order ki qty itni badi nahi ho sakti. Agar koi cell me galti
        # se bada number/ID/date aa gaya (galat column), to use 0 maan lo — warna
        # Total Final Qty kharab (10^16 jaisa) ho jata tha.
        if not (-100000 <= qty <= 100000): qty = 0.0
        if not (-100000 <= ret <= 100000): ret = 0.0

        grand_final_qty += qty
        grand_net_revenue += rev

        dt = parse_date_any(r.get(C_DATE,"")) if C_DATE else None
        date_iso = dt.strftime("%Y-%m-%d") if dt else "N/A"
        dt_o = parse_date_any(r.get(C_ODATE,"")) if C_ODATE else None
        order_date_iso = dt_o.strftime("%Y-%m-%d") if dt_o else "N/A"
        
        # FY logic
        fy = norm_fy(r.get(C_FY,"")) if C_FY else ""
        if not fy:
            fy = fy_bounds(dt if dt else now_ist())[0] if dt else "N/A"
        
        # Period KPIs (Aggregated across ALL rows, even without SKU)
        if dt is not None:
            d0 = dt.replace(hour=0, minute=0, second=0, microsecond=0)
            if d0 == yest_dt:
                kpi_yesterday += rev
            if cm_start <= d0 <= today_dt.replace(hour=23, minute=59, second=59):
                kpi_month += rev
            mk = d0.strftime("%Y-%m")
            if mk == lm_key: kpi_last_month += rev
            if mk == ly_key: kpi_last_year_month += rev

        if fy != "N/A":
            if fy == fy_label_cur: kpi_fy += rev
            elif fy == fy_label_prev: kpi_prev_fy += rev
        elif dt is not None:
            if fy_start_cur_n <= dt <= fy_end_cur_n: kpi_fy += rev

        raw_sku = clean(r.get(C_SKU,"")) if C_SKU else ""
        if not raw_sku: continue
        
        # ── Fuzzy + Alphanumeric Match ──
        n_key = re.sub(r'[^A-Z0-9]', '', raw_sku.upper())
        mapped_sku = raw_sku.upper()  # Default exactly as it is

        if n_key in inv_skus_map:
            mapped_sku = inv_skus_map[n_key]
        elif FAST_LOAD:
            # FAST: difflib fuzzy skip — exact/normalized match na mile to raw
            # key hi use karo. Yeh 55k/59k wala atakna khatam karta hai.
            mapped_sku = raw_sku.upper()
        else:
            # SPEED: fuzzy result memoized — same SKU baar-baar fuzzy nahi chalti
            # (54k rows x 10k keys ka difflib hi pehle minutes kha raha tha)
            cached = _fuzzy_cache.get(n_key)
            if cached is not None:
                mapped_sku = cached
            else:
                cands = _prefix_buckets.get(n_key[:4]) or []
                matches = difflib.get_close_matches(n_key, cands, n=1, cutoff=0.8) if cands else []
                mapped_sku = inv_skus_map[matches[0]] if matches else raw_sku.upper()
                _fuzzy_cache[n_key] = mapped_sku
        
        cust = norm_cust(r.get(C_CUST,"Unknown")) if C_CUST else "Unknown"
        typ  = norm_type(r.get(C_TYPE,"Regular")) if C_TYPE else "Regular"

        # Channel — customer name (original) + type se. (Website override se pehle
        # compute karo taaki Ecom platform naam detect ho sake.)
        channel = calc_channel(cust, typ)
        sub_channel = calc_sub_channel(cust, channel, typ)   # marketplace-level

        # Type = Website ke orders me asli customer naam (D2C buyers) nahi dikhana —
        # uski jagah "Website" hi customer ke roop me aaye.
        if str(typ).strip().lower() == "website":
            cust = "Website"

        custs.add(cust); types_.add(typ); channels_.add(channel)
        sub_channels_.add(sub_channel)
        if fy != "N/A": fyears.add(fy)

        # Return amount = return qty × us transaction ki selling price (COSA F × H)
        entry = {"qty":qty,"rev":rev,"sp":sp,"ret":ret,"ret_amt":float(ret*sp),
                 "date":_si(date_iso),"order_date":_si(order_date_iso),"cust":_si(cust),"type":_si(typ),
                 "channel":_si(channel),"sub_channel":_si(sub_channel),"fy":_si(fy)}
        
        if mapped_sku not in sales_exact: sales_exact[mapped_sku] = {"entries":[],"total_rev":0.0}
        sales_exact[mapped_sku]["entries"].append(entry)
        sales_exact[mapped_sku]["total_rev"] += rev

    # MEMORY: sales dataframe ka kaam khatam — turant free (60-120MB bachat)
    try:
        del cosa
        _DF_REFS.pop("cosa", None)
        _gc.collect()
    except Exception:
        pass

    # ── Rakhi sales source: dedicated cossa_orderdate sheet ───────────────
    # Every Rakhi table/KPI/export must use Order Date, not Dispatch Date.
    # Keep only RKH/CMB rows so the extra source adds very little memory.
    rakhi_sales_exact = {}
    try:
        _wstage("fetching", "Downloading order-date sales sheet for Rakhi…")
        cosa_od = _fetch_csv_fresh(COSA_ORDERDATE_URL)
        _DF_REFS["cosa_orderdate"] = cosa_od
        cosa_od.columns = [str(c).strip() for c in cosa_od.columns]
        od_cols = list(cosa_od.columns)
        def _od_at(i): return od_cols[i] if len(od_cols) > i else None

        OD_DATE = (find_col(
            cosa_od.columns,
            "cossa_orderdate", "cosa_orderdate", "Cossa Order Date", "COSA Order Date",
            "Order Date", "order date", "orderdate"
        ) or _od_at(0))
        OD_FY   = _od_at(1) or find_col(cosa_od.columns, "FY Year", "fy", "financial year")
        OD_SKU  = _od_at(2) or find_col(cosa_od.columns, "SKU", "item code")
        OD_QTY  = (find_col(cosa_od.columns, "Final Qty", "final quantity", "final_qty")
                   or _od_at(6) or find_col(cosa_od.columns, "qty", "quantity") or _od_at(5))
        OD_RET  = find_col(cosa_od.columns, "Return Qty", "return qty", "returns", "returned qty") or _od_at(5)
        OD_SP   = find_col(cosa_od.columns, "Selling Price", "selling price", "sp", "unit price") or _od_at(7)
        OD_REV  = _od_at(8) or find_col(cosa_od.columns, "Net Revenue", "net rev", "revenue")
        OD_CUST = _od_at(9) or find_col(cosa_od.columns, "Customer Name", "customer", "client", "party")
        OD_TYPE = _od_at(10) or find_col(cosa_od.columns, "Type", "channel", "mode")

        dbg["cossa_orderdate_cols"] = od_cols
        dbg["cossa_orderdate_resolved"] = {
            "date": OD_DATE, "fy": OD_FY, "sku": OD_SKU, "qty": OD_QTY,
            "return": OD_RET, "sp": OD_SP, "revenue": OD_REV,
            "customer": OD_CUST, "type": OD_TYPE,
        }

        od_total = len(cosa_od)
        for od_i, r in enumerate(_df_chunks(cosa_od)):
            if (od_i % 3000) == 0:
                _wstage("processing", "Indexing Rakhi orders by Order Date…", od_i, od_total)

            dt_od = parse_date_any(r.get(OD_DATE, "")) if OD_DATE else None
            if dt_od is None:
                continue
            order_date_iso = dt_od.strftime("%Y-%m-%d")

            raw_sku = clean(r.get(OD_SKU, "")) if OD_SKU else ""
            if not raw_sku:
                continue
            n_key = re.sub(r'[^A-Z0-9]', '', raw_sku.upper())
            mapped_sku = raw_sku.upper()
            if n_key in inv_skus_map:
                mapped_sku = inv_skus_map[n_key]
            elif not FAST_LOAD:
                cached = _fuzzy_cache.get("OD:" + n_key)
                if cached is not None:
                    mapped_sku = cached
                else:
                    cands = _prefix_buckets.get(n_key[:4]) or []
                    matches = difflib.get_close_matches(n_key, cands, n=1, cutoff=0.8) if cands else []
                    mapped_sku = inv_skus_map[matches[0]] if matches else raw_sku.upper()
                    _fuzzy_cache["OD:" + n_key] = mapped_sku

            # Rakhi page only needs direct Rakhi SKUs and CMB gift sets.
            if not re.match(r"^(RKH|CMB)", str(mapped_sku or "").strip(), re.I):
                continue

            qty = to_num(r.get(OD_QTY, 0)) if OD_QTY else 0.0
            ret = to_num(r.get(OD_RET, 0)) if OD_RET else 0.0
            sp  = to_num(r.get(OD_SP, 0)) if OD_SP else 0.0
            rev = to_num(r.get(OD_REV, 0)) if OD_REV else 0.0
            if not (-100000 <= qty <= 100000): qty = 0.0
            if not (-100000 <= ret <= 100000): ret = 0.0

            fy = norm_fy(r.get(OD_FY, "")) if OD_FY else ""
            if not fy:
                fy = fy_bounds(dt_od)[0]
            cust = norm_cust(r.get(OD_CUST, "Unknown")) if OD_CUST else "Unknown"
            typ  = norm_type(r.get(OD_TYPE, "Regular")) if OD_TYPE else "Regular"
            channel = calc_channel(cust, typ)
            sub_channel = calc_sub_channel(cust, channel, typ)
            if str(typ).strip().lower() == "website":
                cust = "Website"

            entry = {
                "qty": qty, "rev": rev, "sp": sp, "ret": ret,
                "ret_amt": float(ret * sp),
                "date": _si(order_date_iso),
                "order_date": _si(order_date_iso),
                "cust": _si(cust), "type": _si(typ),
                "channel": _si(channel), "sub_channel": _si(sub_channel),
                "fy": _si(fy),
            }
            bucket = rakhi_sales_exact.setdefault(mapped_sku, {"entries": [], "total_rev": 0.0})
            bucket["entries"].append(entry)
            bucket["total_rev"] += rev

        dbg["cossa_orderdate_rakhi_skus"] = len(rakhi_sales_exact)
        dbg["cossa_orderdate_rakhi_rows"] = sum(len(v.get("entries", [])) for v in rakhi_sales_exact.values())
    except Exception as e:
        dbg["errors"].append(f"cossa_orderdate: {e}")
    finally:
        try:
            del cosa_od
        except Exception:
            pass
        _DF_REFS.pop("cosa_orderdate", None)
        _gc.collect()

    # Safe fallback only when the main source genuinely contains an Order Date
    # column. We never substitute Dispatch Date for Rakhi.
    if not rakhi_sales_exact and C_ODATE:
        for sku_key, sd in sales_exact.items():
            if not re.match(r"^(RKH|CMB)", str(sku_key or "").strip(), re.I):
                continue
            od_entries = []
            for old_e in sd.get("entries", []):
                od = old_e.get("order_date")
                if not od or od == "N/A":
                    continue
                ne = dict(old_e)
                ne["date"] = od
                ne["order_date"] = od
                od_entries.append(ne)
            if od_entries:
                rakhi_sales_exact[sku_key] = {
                    "entries": od_entries,
                    "total_rev": sum(float(e.get("rev") or 0) for e in od_entries),
                }

    _lm = float(kpi_last_month); _ly = float(kpi_last_year_month)
    _yoy = round(((_lm - _ly) / _ly * 100), 1) if _ly else None
    period_kpis = {
        "total":      grand_net_revenue,
        "yesterday":  float(kpi_yesterday),
        "this_month": float(kpi_month),
        "this_fy":    float(kpi_fy),
        "prev_fy":    float(kpi_prev_fy),
        "fy_current_label": fy_label_cur,
        "fy_prev_label":    fy_label_prev,
        "last_month":            _lm,
        "last_month_label":      lm_label,
        "last_year_month":       _ly,
        "last_year_month_label": ly_label,
        "mom_yoy_pct":           _yoy,
    }
    
    dbg["grand_net_revenue"] = grand_net_revenue
    dbg["grand_final_qty"]   = grand_final_qty

    # ── Compile inventory items ──────────────────────────────
    compiled  = []
    sku_list  = []
    taxons, platings = set(), set()
    today = now_ist()
    d7   = today - timedelta(days=7)
    d15  = today - timedelta(days=15)
    d30  = today - timedelta(days=30)
    d90  = today - timedelta(days=90)
    d180 = today - timedelta(days=180)
    d365 = today - timedelta(days=365)

    def qty_since(entries, dt_cutoff):
        total = 0.0
        for e in entries:
            if e["date"] == "N/A": continue
            try:
                if datetime.strptime(e["date"],"%Y-%m-%d").replace(tzinfo=TZ) >= dt_cutoff:
                    total += e["qty"]
            except: pass
        return int(round(total))

    # SPEED: date windows ko ISO strings me badlo — har entry par strptime ke
    # bajay sirf string-compare (YYYY-MM-DD lexical compare = date compare).
    # Yeh "Compiling products" wala atakna hata deta hai (10k SKU x N entries
    # x 6 windows ka strptime hi pure load tha).
    s7   = d7.strftime("%Y-%m-%d")
    s15  = d15.strftime("%Y-%m-%d")
    s30  = d30.strftime("%Y-%m-%d")
    s90  = d90.strftime("%Y-%m-%d")
    s180 = d180.strftime("%Y-%m-%d")
    s365 = d365.strftime("%Y-%m-%d")
    yest_s = (today - timedelta(days=1)).strftime("%Y-%m-%d")
    month_s = today.strftime("%Y-%m")

    fy_current, _, _ = fy_bounds(today)
    fy_previous = prev_fy_label(fy_current)

    def _agg_entries(ent):
        """Ek hi pass me saare per-SKU numbers — qty windows, rev windows,
        totals, first/last date, customers. String compare, zero strptime."""
        q7=q15=q1m=q3m=q6m=q1y=0.0
        tot_rev=tot_qty=0.0
        tot_ret=tot_ret_amt=0.0
        rev_y=rev_m=rev_fy=rev_pfy=0.0
        custs=set()
        first_d=None; last_d=None
        for e in ent:
            d=e["date"]; q=e["qty"]; rv=e["rev"]
            tot_rev+=rv; tot_qty+=q
            tot_ret += e.get("ret") or 0
            tot_ret_amt += e.get("ret_amt") or 0
            custs.add(e["cust"])
            if e["fy"]==fy_current: rev_fy+=rv
            elif e["fy"]==fy_previous: rev_pfy+=rv
            if d!="N/A":
                if d>=s7:   q7+=q
                if d>=s15:  q15+=q
                if d>=s30:  q1m+=q
                if d>=s90:  q3m+=q
                if d>=s180: q6m+=q
                if d>=s365: q1y+=q
                if d==yest_s: rev_y+=rv
                if d.startswith(month_s): rev_m+=rv
                if first_d is None or d<first_d: first_d=d
                if last_d is None or d>last_d: last_d=d
        return {
            "q7":int(round(q7)),"q15":int(round(q15)),"q1m":int(round(q1m)),
            "q3m":int(round(q3m)),"q6m":int(round(q6m)),"q1y":int(round(q1y)),
            "tot_rev":tot_rev,"tot_qty":int(round(tot_qty)),
            "tot_ret":int(round(tot_ret)),"tot_ret_amt":tot_ret_amt,
            "rev_y":rev_y,"rev_m":rev_m,"rev_fy":rev_fy,"rev_pfy":rev_pfy,
            "ncust":len(custs),"first":first_d or "N/A","last":last_d or "N/A",
        }

    seen_skus = set()
    _n_inv = len(inv)
    for _ii, r in enumerate(_df_chunks(inv, 2500)):
        if (_ii % 1500) == 0:
            _wstage("processing", "Compiling products…", _ii, _n_inv)
        raw = clean(r.get(I_SKU,"")) if I_SKU else ""
        if not raw: continue
        
        dedupe_key = raw.strip().upper()
        if dedupe_key in seen_skus:
            continue
        seen_skus.add(dedupe_key)
        sku_list.append(raw)

        taxon = norm_taxon(r.get(I_TAX,"General")) if I_TAX else "General"
        plat  = clean(r.get(I_PLT,"N/A"),"N/A")        if I_PLT else "N/A"
        dims  = clean(r.get(I_DIM,""))                  if I_DIM else ""
        # Launch Date — kisi bhi format mein ho, robust parse
        launch_key, launch_label, launch_iso = "", "", ""
        if I_LNCH:
            _lv = r.get(I_LNCH, "")
            if _lv is not None and str(_lv).strip() and str(_lv).strip().lower() not in ("nan", "na", "n/a", "-", "none"):
                _sv = str(_lv).strip()
                _ld = pd.NaT
                if re.match(r"^\d{4}[-/]\d{1,2}([-/]\d{1,2})?$", _sv):
                    _ld = pd.to_datetime(_sv, errors="coerce")          # ISO yyyy-mm(-dd)
                if pd.isna(_ld):
                    _ld = pd.to_datetime(_sv, dayfirst=True, errors="coerce")
                if pd.isna(_ld):
                    _ld = pd.to_datetime(_sv, dayfirst=False, errors="coerce")
                if not pd.isna(_ld):
                    launch_iso   = _ld.strftime("%Y-%m-%d")
                    launch_key   = _ld.strftime("%Y-%m")
                    launch_label = _ld.strftime("%B %Y")
        img   = clean(r.get(I_IMG,""))                  if I_IMG else ""
        stk   = to_int(r.get(I_STK,0))                 if I_STK else 0
        stk_3p = to_int(r.get(I_STK_3P,0))             if I_STK_3P else None
        wip   = to_int(r.get(I_WIP,0))                 if I_WIP else 0
        wh_wip = to_int(r.get(I_WH_WIP,0))             if I_WH_WIP else (stk + wip)
        wip_website  = to_int(r.get(I_WIP_WEBSITE,0))  if I_WIP_WEBSITE  else 0
        wip_designer = to_int(r.get(I_WIP_DESIGNER,0)) if I_WIP_DESIGNER else 0
        wip_customer = to_int(r.get(I_WIP_CUSTOMER,0)) if I_WIP_CUSTOMER else 0
        wip_sor      = to_int(r.get(I_WIP_SOR,0))      if I_WIP_SOR      else 0
        blocked      = to_int(r.get(I_BLOCKED,0))       if I_BLOCKED      else 0
        mrp   = to_num(r.get(I_MRP,0))                 if I_MRP  else 0.0
        cost  = to_num(r.get(I_COST,0))                if I_COST else 0.0

        sd  = sales_exact.get(dedupe_key, {"entries": [], "total_rev": 0.0})
        ent = sd["entries"]
        rkh_sd = rakhi_sales_exact.get(dedupe_key, {"entries": [], "total_rev": 0.0})
        rkh_ent = rkh_sd["entries"]

        # Selling Price = COSA col H ka ACTUAL value (latest dated non-zero).
        _sps = [float(e.get("sp") or 0) for e in ent if float(e.get("sp") or 0) > 0]
        avg_sp  = round(sum(_sps) / len(_sps), 2) if _sps else 0.0
        last_sp = 0.0
        _dated_nz = sorted(
            [e for e in ent if e.get("date") not in (None, "N/A") and float(e.get("sp") or 0) > 0],
            key=lambda e: e["date"]
        )
        if _dated_nz:
            last_sp = float(_dated_nz[-1].get("sp") or 0)
        elif _sps:
            last_sp = _sps[-1]

        # Discount % — OVERALL AVERAGE discount across ALL sales (qty-weighted:
        # total revenue / total qty vs MRP). Pehle last_selling_price ka istemal
        # hota tha jo GALAT tha — agar sirf AAKHRI order full-price par hota
        # tha to poora SKU 0% discount dikhata tha, chahe baaki saari sales
        # discounted hoti thi. Ab yeh number sahi "overall average" hai, aur
        # UI mein filter (date/channel/type) lagne par isी method se
        # filtered discount % nikala jaata hai — Discount Leakage tab bhi
        # isी method se match karta hai (neeche dekho).
        _tot_rev_all = sum(float(e.get("rev") or 0) for e in ent)
        _tot_qty_all = sum(float(e.get("qty") or 0) for e in ent)
        _overall_avg_sp = (_tot_rev_all / _tot_qty_all) if _tot_qty_all > 0 else 0.0
        if mrp > 0 and _overall_avg_sp > 0 and _overall_avg_sp < mrp:
            discount_pct = round((mrp - _overall_avg_sp) / mrp * 100, 1)
        else:
            discount_pct = 0.0

        A = _agg_entries(ent)   # ek hi pass me saare numbers
        _cn_name_for_item = cn_display_name(raw) or raw
        _cn_tags_for_item = cn_classify_tags(_cn_name_for_item)

        stone_details_raw = clean(r.get(I_STONE,"")) if I_STONE else ""
        combo_details_raw = clean(r.get(I_COMBO_DETAILS,"")) if I_COMBO_DETAILS else ""
        stone_details = stone_details_raw or (combo_details_raw if re.match(r"^\s*cmb", raw or "", re.I) else "")
        gift_set_stone_details = stone_details if (
            re.match(r"^\s*cmb", raw or "", re.I) and stone_details.strip()
        ) else ""

        item = {
            "sku":         raw,
            "sku_name":    cn_sku_label(raw),
            "is_religious": _cn_tags_for_item["religious"],
            "is_seasonal":  _cn_tags_for_item["seasonal"],
            "image_url":   img,
            "inv_stock":   stk,
            "inv_stock_3p": stk_3p,
            "inv_wip":     wip,
            "wh_wip":      wh_wip,
            "inv_wip_website":  wip_website,
            "inv_wip_designer": wip_designer,
            "inv_wip_customer": wip_customer,
            "inv_wip_sor":      wip_sor,
            "blocked_qty":      blocked,
            "total_inv":   stk + wip,
            "mrp":         mrp,
            "cost":        cost,
            "website_selling_price": cn_website_selling_price(raw),
            "avg_selling_price":  avg_sp,
            "last_selling_price": last_sp,
            "aov_per_piece":      avg_sp,       # per-piece average order value (avg selling price/unit)
            "discount_pct":       discount_pct, # MRP se discount % (Discount Leakage tab jaisa hi method)
            "taxon":       _si(taxon),
            "plating":     _si(plat),
            "dimensions":  _si(dims),
            "launch_date":  _si(launch_iso),
            "launch_key":   _si(launch_key),
            "launch_month": _si(launch_label),
            "combo_skus":   stone_details,
            "gift_set_stone_details": gift_set_stone_details,
            "pack_details": clean(r.get(I_PACK,""))  if I_PACK  else "",
            "stone_color":  clean(r.get(I_STONE_COLOR,"")) if I_STONE_COLOR else "",
            "sales_entries": ent,
            "rakhi_sales_entries": rkh_ent,
            "website_customer_events": website_customer_events.get(dedupe_key, []),
            "website_city_events": website_city_events.get(dedupe_key, []),
            "website_payment_events": website_payment_events.get(dedupe_key, []),
            "total_net_revenue": float(A["tot_rev"]),
            "final_qty":   A["tot_qty"],
            "return_qty":   A["tot_ret"],
            "return_amount": float(A["tot_ret_amt"]),
            "customer_count": A["ncust"],
            "qty_7d":  A["q7"],
            "qty_15d": A["q15"],
            "qty_1m":  A["q1m"],
            "qty_3m":  A["q3m"],
            "qty_6m":  A["q6m"],
            "qty_1y":  A["q1y"],
            "rev_yesterday": A["rev_y"],
            "rev_month":     A["rev_m"],
            "rev_fy":        A["rev_fy"],
            "rev_prev_fy":   A["rev_pfy"],
            "dispatch_count": len(ent),
            "first_dispatch_date": A["first"],
            "last_dispatch_date":  A["last"],
            "forecast_30d": simple_forecast(ent, 30),
            "status": "",
        }
        # Reorder Qty = next 60 din ki expected demand (production lead-time cover)
        # minus jo already available hai (stock + WIP). 0 se neeche nahi.
        _avail = (item["inv_stock"] or 0) + (item["inv_wip"] or 0)
        _demand60 = simple_forecast(ent, 60)
        item["forecast_60d"] = _demand60
        item["reorder_qty"]  = max(0, int(round(_demand60 - _avail)))
        item["status"] = classify_status(item, month_s)
        _flags, _best_chan, _best_chan_rev, _days_since, _best_mkt, _best_mkt_rev, _trend = _compute_alerts_and_channel(item, today)
        item["alert_flags"] = _flags
        item["best_channel"] = _si(_best_chan)
        item["best_channel_revenue"] = round(_best_chan_rev, 0)
        item["best_marketplace"] = _si(_best_mkt)
        item["best_marketplace_revenue"] = round(_best_mkt_rev, 0)
        item["trend"] = _trend or ""
        item["days_since_last_sale"] = _days_since if _days_since is not None else -1
        compiled.append(item)
        taxons.add(taxon)
        if plat != "N/A": platings.add(plat)

    # ── ORPHAN SKUs: cossa sheet ke SKU jo All Product (inventory) sheet
    # mein NAHI hain — unka revenue Total Net Rev jaise unfiltered KPIs mein
    # toh count hota tha (kyunki wo grand_net_revenue/period_kpis seedhe COSA
    # rows se ban rahe the), par kisi bhi card/filter/SKU-view mein kabhi
    # nahi dikhta tha, isliye Type/Taxon/Customer/Date filter lagate hi
    # numbers "total" se kam dikhte the. Ab unhe bhi ek minimal item banake
    # add kar rahe hain (taxon = "Not In Inventory") taaki filtered KPIs
    # bhi sheet ke total se exactly match karein. In SKUs ko All Product
    # sheet mein add karna hi asli data-hygiene fix hai — yeh sirf display
    # ko sahi karta hai.
    for orphan_key, sd in sales_exact.items():
        if orphan_key in seen_skus:
            continue
        ent = sd["entries"]
        if not ent:
            continue
        rkh_ent = rakhi_sales_exact.get(orphan_key, {"entries": []}).get("entries", [])
        seen_skus.add(orphan_key)
        sku_list.append(orphan_key)
        A = _agg_entries(ent)
        _cn_name_o = cn_display_name(orphan_key) or orphan_key
        _cn_tags_o = cn_classify_tags(_cn_name_o)
        item = {
            "sku": orphan_key, "sku_name": cn_sku_label(orphan_key),
            "is_religious": _cn_tags_o["religious"], "is_seasonal": _cn_tags_o["seasonal"],
            "image_url": "", "inv_stock": 0, "inv_wip": 0, "wh_wip": 0,
            "inv_wip_website": 0, "inv_wip_designer": 0, "inv_wip_customer": 0, "inv_wip_sor": 0,
            "blocked_qty": 0, "total_inv": 0, "mrp": 0.0, "cost": 0.0,
            "website_selling_price": cn_website_selling_price(orphan_key),
            "avg_selling_price": 0.0, "last_selling_price": 0.0, "aov_per_piece": 0.0,
            "discount_pct": 0.0, "taxon": "Not In Inventory", "plating": "N/A",
            "dimensions": "", "launch_date": "", "launch_key": "", "launch_month": "",
            "combo_skus": "", "pack_details": "", "stone_color": "", "sales_entries": ent,
            "rakhi_sales_entries": rkh_ent,
            "website_customer_events": website_customer_events.get(orphan_key, []),
            "website_city_events": website_city_events.get(orphan_key, []),
            "website_payment_events": website_payment_events.get(orphan_key, []),
            "total_net_revenue": float(A["tot_rev"]), "final_qty": A["tot_qty"],
            "return_qty": A["tot_ret"], "return_amount": float(A["tot_ret_amt"]),
            "customer_count": A["ncust"],
            "qty_7d": A["q7"], "qty_15d": A["q15"], "qty_1m": A["q1m"],
            "qty_3m": A["q3m"], "qty_6m": A["q6m"], "qty_1y": A["q1y"],
            "rev_yesterday": A["rev_y"], "rev_month": A["rev_m"],
            "rev_fy": A["rev_fy"], "rev_prev_fy": A["rev_pfy"],
            "dispatch_count": len(ent), "first_dispatch_date": A["first"],
            "last_dispatch_date": A["last"], "forecast_30d": simple_forecast(ent, 30),
            "status": "",
        }
        item["forecast_60d"] = simple_forecast(ent, 60)
        item["reorder_qty"] = 0
        item["status"] = classify_status(item, month_s)
        _flags, _best_chan, _best_chan_rev, _days_since, _best_mkt, _best_mkt_rev, _trend = _compute_alerts_and_channel(item, today)
        item["alert_flags"] = _flags
        item["best_channel"] = _si(_best_chan)
        item["best_channel_revenue"] = round(_best_chan_rev, 0)
        item["best_marketplace"] = _si(_best_mkt)
        item["best_marketplace_revenue"] = round(_best_mkt_rev, 0)
        item["trend"] = _trend or ""
        item["days_since_last_sale"] = _days_since if _days_since is not None else -1
        item["combo_details"] = []
        compiled.append(item)
        taxons.add("Not In Inventory")

    # ── COMBO/GIFT-SET enrichment ──
    # Stone Details (combo_skus) me jo SKUs likhe hain, un sabki Inv Stock + WIP
    # nikaal ke saath jod do. Gift Set / combo SKUs me ye details dikhengi.
    # WIP channel-wise bhi store hoti hai taaki Type filter par us channel ki
    # WIP dikhe (Website/SOR/Designer), warna total.
    _stock_map = {}
    _item_map = {}
    for it in compiled:
        ku = str(it["sku"]).strip().upper()
        _item_map[ku] = it
        _stock_map[ku] = {
            "stock": int(it.get("inv_stock") or 0),
            "stock_3p": int(it.get("inv_stock_3p") or 0) if it.get("inv_stock_3p") is not None else None,
            "wip":   int(it.get("inv_wip") or 0),
            "wip_website":  int(it.get("inv_wip_website") or 0),
            "wip_sor":      int(it.get("inv_wip_sor") or 0),
            "wip_designer": int(it.get("inv_wip_designer") or 0),
            "wip_customer": int(it.get("inv_wip_customer") or 0),
        }
    _sku_re = re.compile(r"[A-Za-z]{1,5}[-_ ]?\d{2,5}(?:[-_(][A-Za-z0-9)]+)*")
    for it in compiled:
        combo = it.get("combo_skus") or ""
        it["combo_details"] = []
        if not combo or not combo.strip():
            continue
        seen = set()
        for tok in _sku_re.findall(combo):
            key = tok.strip().upper().replace(" ", "")
            # normalize: "BH 1225" -> "BH-1225" agar map me dash-version ho
            cand = key
            if cand not in _stock_map and ("-" not in cand and "_" not in cand):
                # try inserting dash between letters and digits
                mm = re.match(r"^([A-Za-z]+)(\d.*)$", cand)
                if mm:
                    cand = mm.group(1) + "-" + mm.group(2)
            if cand in seen:
                continue
            seen.add(cand)
            info = _stock_map.get(cand)
            ci = _item_map.get(cand)   # combo SKU ka full item (saari details ke liye)
            it["combo_details"].append({
                "sku": cand,
                "sku_name": (ci.get("sku_name") if ci else ""),
                "stone_color": (ci.get("stone_color") if ci else ""),
                "image_url": (ci.get("image_url") if ci else ""),
                "inv_stock": info["stock"] if info else 0,
                "inv_stock_3p": info["stock_3p"] if info and info.get("stock_3p") is not None else (info["stock"] if info else 0),
                "inv_wip":   info["wip"] if info else 0,
                "inv_wip_website":  info["wip_website"] if info else 0,
                "inv_wip_sor":      info["wip_sor"] if info else 0,
                "inv_wip_designer": info["wip_designer"] if info else 0,
                "inv_wip_customer": info["wip_customer"] if info else 0,
                "blocked_qty": (ci.get("blocked_qty") if ci else 0),
                # poori details — CMB jaisi (combo SKU khud bhi inventory me hai)
                "qty_7d":   (ci.get("qty_7d") if ci else 0) or 0,
                "qty_15d":  (ci.get("qty_15d") if ci else 0) or 0,
                "qty_1m":   (ci.get("qty_1m") if ci else 0) or 0,
                "final_qty":(ci.get("final_qty") if ci else 0) or 0,
                "forecast_60d": (ci.get("forecast_60d") if ci else 0) or 0,
                "reorder_qty":  (ci.get("reorder_qty") if ci else 0) or 0,
                "mrp":      (ci.get("mrp") if ci else 0) or 0,
                "taxon":    (ci.get("taxon") if ci else ""),
                "plating":  (ci.get("plating") if ci else ""),
                "found":     info is not None,
            })

    CACHE["data"] = (
        compiled,
        sorted(taxons),
        sorted(types_),
        sorted(custs),
        sorted(platings),
        sorted(set(sku_list)),
        sorted(fyears, reverse=True),
        fy_current, fy_previous,
        today.strftime("%Y-%m-%d"),
        (today-timedelta(days=1)).strftime("%Y-%m-%d"),
        today.strftime("%Y-%m"),
        grand_net_revenue,
        grand_final_qty,
        period_kpis,
    )
    # channels list (Type filter ke saath Channel filter ke liye)
    CACHE["channels"] = sorted([c for c in channels_ if c])
    CACHE["sub_channels"] = sorted([c for c in sub_channels_ if c])
    CACHE["website_payment_summary"] = website_payment_summary
    CACHE["ts"]    = time.time()
    _COSTS_CACHE["rows"] = None   # profit margin cache bhi refresh karo
    CACHE["debug"] = dbg
    return CACHE["data"]

