def _pincode_city_hint(pin, state):
    digits = re.sub(r"\D", "", str(pin or ""))
    if len(digits) < 3:
        return ""
    prefix = int(digits[:3])
    hint = _PIN3_CITY_HINTS.get(prefix)
    if hint and hint[0] == state:
        return hint[1]
    if state == "Delhi":
        return "New Delhi"
    if state == "Chandigarh":
        return "Chandigarh"
    return f"PIN {prefix} Area"


def _extract_city_pin_from_address(addr):
    """Extract city and the final 6-digit PIN from free-form billing address.

    Supports `CITY-PIN`, `CITY, STATE - PIN`, line breaks and trailing India.
    The final PIN is treated as authoritative; city/state consistency is
    handled by `_normalize_city_for_state`.
    """
    s = str(addr or "").strip()
    if not s:
        return "", ""
    matches = list(re.finditer(r"(?<!\d)([1-8]\d{5})(?!\d)", s))
    if not matches:
        return "", ""
    m = matches[-1]
    pin = m.group(1)
    prefix = s[:m.start()].strip(" \t\r\n,;:-–—/")
    if not prefix:
        return "", pin

    parts = [re.sub(r"\s+", " ", p).strip(" .;:-–—/")
             for p in re.split(r"[,\n]+", prefix)]
    parts = [p for p in parts if p]
    if not parts:
        return "", pin

    # Drop trailing country/state-only segments, then use the nearest city
    # segment before the PIN.
    while parts and _geo_key(parts[-1]) in {"india", "bharat"}:
        parts.pop()
    pin_state = _pincode_to_state(pin)
    while len(parts) > 1 and _geo_key(parts[-1]) in _STATE_KEY_TO_NAME:
        tail_key = _geo_key(parts[-1])
        city_alias = _CITY_STATE_ALIASES.get(tail_key)
        # Puducherry/Delhi/Chandigarh can be both State/UT and city names.
        # Keep the token when it is a valid city for the PIN-derived State.
        if city_alias and city_alias[0] == pin_state:
            break
        parts.pop()
    if not parts:
        return "", pin
    city = parts[-1]

    # Tail may be `Jaipur - Rajasthan`; remove a trailing State token.
    chunks = [c.strip() for c in re.split(r"\s*[-–—/]\s*", city) if c.strip()]
    while len(chunks) > 1 and _geo_key(chunks[-1]) in _STATE_KEY_TO_NAME:
        tail_key = _geo_key(chunks[-1])
        city_alias = _CITY_STATE_ALIASES.get(tail_key)
        if city_alias and city_alias[0] == pin_state:
            break
        chunks.pop()
    city = chunks[-1] if chunks else city
    city = re.sub(r"\s+", " ", city).strip(" .,-")
    return city.title(), pin


def _extract_pin_from_address(addr):
    """Backward-compatible PIN-only helper."""
    return _extract_city_pin_from_address(addr)[1]


def _normalize_city_for_state(city, state, pin=""):
    """Validate address city against PIN-derived State and correct mismatch.

    A known cross-State city never remains under the wrong State.  When the
    source city conflicts with the PIN, a conservative PIN-prefix hint is
    used (for example a 302xxx Rajasthan address becomes Jaipur rather than
    showing Darjeeling under Rajasthan).
    """
    city = re.sub(r"\s+", " ", str(city or "")).strip(" .,-")
    state = _STATE_KEY_TO_NAME.get(_geo_key(state), str(state or "").strip())
    if not state:
        return city.title()

    key = _geo_key(city)
    known = _CITY_STATE_ALIASES.get(key)
    if not city or key in {"india", "bharat"}:
        return _pincode_city_hint(pin, state)
    # Puducherry, Delhi and Chandigarh can be both State/UT and city names.
    # Treat them as cities when the PIN-derived State agrees.
    if key in _STATE_KEY_TO_NAME and not (known and known[0] == state):
        return _pincode_city_hint(pin, state)

    if known:
        known_state, canonical = known
        if known_state != state:
            return _pincode_city_hint(pin, state)
        city = canonical

    if state == "Delhi" and key in {
        "north", "south", "east", "west", "north east", "north west",
        "south east", "south west", "central"
    }:
        city = f"{city} Delhi"
    return city.title()


def _fetch_rkh_sku_city_rows():
    """Build validated Website order city rows for the Rakhi State/UT table.

    PIN-derived State is authoritative. Cancelled/failed and explicit
    zero/negative-quantity rows are excluded. If no Qty column exists, one
    row is treated as one sold unit. Diagnostics expose how many source city
    labels were corrected so data quality can be monitored.
    """
    if _RKH_CITY_CACHE["rows"] is not None and (time.time() - _RKH_CITY_CACHE["ts"] < 600):
        return _RKH_CITY_CACHE["rows"], _RKH_CITY_CACHE.get("diag", {})
    out = []
    diag = {
        "rows_total": 0, "rows_used": 0, "columns_found": False,
        "rows_cancelled": 0, "rows_nonpositive_qty": 0,
        "city_labels_corrected": 0, "error": None,
    }
    try:
        df = _fetch_csv_fresh(RAKHI_WEBSITE_ADDR_URL)
        df.columns = [str(c).strip() for c in df.columns]
        cols = list(df.columns)
        diag["rows_total"] = len(df)
        diag["all_columns"] = cols[:20]
        C_SKU = find_col(cols, "New SKU", "SKU", "sku code", "product sku", "item sku") \
                or (cols[0] if len(cols) > 0 else None)
        qty_keys = {
            "finalqty", "finalquantity", "soldqty", "saleqty",
            "orderqty", "orderedqty", "totalqty", "quantity", "qty"
        }
        C_QTY = next((c for c in cols if re.sub(r"[^a-z0-9]", "", c.lower()) in qty_keys), None)
        C_ADDR = find_col(cols, "Final Billing Address", "billing address", "final address", "address") \
                 or (cols[4] if len(cols) > 4 else None)
        C_STATUS = find_col(cols, "Sale Order Status", "Order Status", "status")
        diag["sku_col"] = C_SKU
        diag["qty_col"] = C_QTY
        diag["addr_col"] = C_ADDR
        diag["status_col"] = C_STATUS
        if C_SKU and C_ADDR:
            diag["columns_found"] = True
            for _, r in df.iterrows():
                status = str(r.get(C_STATUS, "") or "").strip().casefold() if C_STATUS else ""
                if status and any(x in status for x in ("cancel", "void", "failed")):
                    diag["rows_cancelled"] += 1
                    continue
                sku = str(r.get(C_SKU, "") or "").strip()
                if not sku:
                    continue
                raw_city, pin = _extract_city_pin_from_address(r.get(C_ADDR, ""))
                if not pin:
                    continue
                state = _pincode_to_state(pin)
                if not state:
                    continue
                city = _normalize_city_for_state(raw_city, state, pin)
                if _geo_key(city) != _geo_key(raw_city):
                    diag["city_labels_corrected"] += 1
                qty = to_num(r.get(C_QTY, 0)) if C_QTY else 1.0
                if C_QTY and qty <= 0:
                    diag["rows_nonpositive_qty"] += 1
                    continue
                if not C_QTY:
                    qty = 1.0
                out.append({
                    "sku": sku, "qty": float(qty), "state": state,
                    "city": city, "pin": pin,
                })
                diag["rows_used"] += 1
        else:
            diag["error"] = "Could not find SKU / Final Billing Address columns in the sheet."
    except Exception as e:
        diag["error"] = str(e)[:300]
        print("Rakhi SKU-city rows fetch failed:", str(e)[:160])
    _RKH_CITY_CACHE["rows"] = out
    _RKH_CITY_CACHE["diag"] = diag
    _RKH_CITY_CACHE["ts"] = time.time()
    return out, diag

@app.route("/api/rakhi-cities")
def api_rakhi_cities():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        rows, diag = _fetch_rkh_sku_city_rows()
        return jsonify({"rows": rows, "count": len(rows), "diag": diag, "all_states_uts": INDIA_STATES_UTS})
    except Exception as e:
        return jsonify({"error": f"rakhi city rows build failed: {e}"}), 500

@app.route("/api/daily_revenue_glimpse/export.xlsx")
def api_daily_revenue_glimpse_export_xlsx():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        rep = _build_daily_revenue_glimpse()
        rows = rep["rows"]
        tot  = rep["totals"]
        today_dt = now_ist().replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=None)
        title_txt = today_dt.strftime("%d - %b - %Y")

        headers = ["Channel", "YTD", "Last Month", "This Month", "Day Before",
                   "Yesterday", "This Month Target", "Achievement %"]
        n_cols = len(headers)
        NUM_FMT = "[>=10000000]##\\,##\\,##\\,##0;[>=100000]##\\,##\\,##0;##,##0"

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Daily Revenue Glimpse"

        title_fill  = PatternFill("solid", fgColor="000000")
        title_font  = Font(bold=True, color="FFFFFF", size=12)
        head_fill   = PatternFill("solid", fgColor="C9DAF8")
        head_font   = Font(bold=True)
        total_fill  = PatternFill("solid", fgColor="C9DAF8")
        total_font  = Font(bold=True)
        thin = Side(style="thin", color="CCCCCC")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        center = Alignment(horizontal="center", vertical="center")

        # Row 1: title bar
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=n_cols)
        c = ws.cell(row=1, column=1, value=title_txt)
        c.fill = title_fill; c.font = title_font; c.alignment = center
        for col in range(1, n_cols + 1):
            ws.cell(row=1, column=col).fill = title_fill

        # Row 2: header
        for col, h in enumerate(headers, start=1):
            c = ws.cell(row=2, column=col, value=h)
            c.fill = head_fill; c.font = head_font; c.alignment = center; c.border = border

        # Data rows
        r_idx = 3
        for r in rows:
            ws.cell(row=r_idx, column=1, value=r["channel"]).font = Font(bold=True)
            ws.cell(row=r_idx, column=2, value=round(r["ytd"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=3, value=round(r["last_month"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=4, value=round(r["mtd"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=5, value=round(r["day_before"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=6, value=round(r["yesterday"])).number_format = NUM_FMT
            if r["mtd_target"]:
                ws.cell(row=r_idx, column=7, value=round(r["mtd_target"])).number_format = NUM_FMT
                ws.cell(row=r_idx, column=8, value=r["mtd_achievement"])
            else:
                ws.cell(row=r_idx, column=7, value="NA")
                ws.cell(row=r_idx, column=8, value="")
            for col in range(1, n_cols + 1):
                ws.cell(row=r_idx, column=col).border = border
            r_idx += 1

        # TOTAL row
        ws.cell(row=r_idx, column=1, value="TOTAL")
        ws.cell(row=r_idx, column=2, value=round(tot["ytd"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=3, value=round(tot["last_month"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=4, value=round(tot["mtd"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=5, value=round(tot["day_before"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=6, value=round(tot["yesterday"])).number_format = NUM_FMT
        if tot["mtd_target"]:
            ws.cell(row=r_idx, column=7, value=round(tot["mtd_target"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=8, value=tot["mtd_achievement"])
        else:
            ws.cell(row=r_idx, column=7, value="NA")
            ws.cell(row=r_idx, column=8, value="")
        for col in range(1, n_cols + 1):
            cell = ws.cell(row=r_idx, column=col)
            cell.fill = total_fill; cell.font = total_font; cell.border = border

        widths = [26, 14, 14, 14, 12, 12, 16, 14]
        for i, w in enumerate(widths, start=1):
            ws.column_dimensions[get_column_letter(i)].width = w

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)
        fname = f"daily_revenue_glimpse_{today_dt.strftime('%Y-%m-%d')}.xlsx"
        resp = app.response_class(
            bio.read(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        resp.headers["Content-Disposition"] = f"attachment; filename={fname}"
        return resp
    except Exception as e:
        return jsonify({"error": f"excel export failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  📤 OVERALL DETAILS EXPORT (Customer/Date drill-down)
#  Jab Overall Details tab me Customer/Date se search karke
#  Transactions + Pivot (SKU-wise summary) table dikhti hai, wahan
#  ke Export Excel / Export PDF buttons yahan hit karte hain.
#  Frontend jo bhi filtered rows (already filters lagi hui) bhejta
#  hai wahi export hoti hai — image_url "Image Link" column me
#  (Excel) ya photo ke roop me (PDF) shamil hota hai.
# ════════════════════════════════════════════════════════════════
_OVERALL_NUM_FMT = "[>=10000000]##\\,##\\,##\\,##0;[>=100000]##\\,##\\,##0;##,##0"

@app.route("/api/overall_export/xlsx", methods=["POST"])
def api_overall_export_xlsx():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill

        payload = request.get_json(force=True) or {}
        kind  = payload.get("kind", "transactions")
        rows  = payload.get("rows") or []
        title = (payload.get("title") or "overall_details").strip() or "overall_details"
        show_rev = bool(rows) and rows[0].get("revenue") is not None

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Pivot" if kind == "pivot" else "Transactions"

        if kind == "pivot":
            headers = ["Customer", "SKU", "Total Qty"] + (["Net Revenue"] if show_rev else []) \
                      + ["Inv Stock", "Inv (WIP)", "Image Link"]
        else:
            headers = ["Dispatch Date", "SKU", "Customer", "Type", "Sold Qty"] + (["Net Revenue"] if show_rev else []) \
                      + ["Inv Stock", "Inv (WIP)", "Blocked Qty", "Image Link"]

        ws.append(headers)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF")
            c.fill = PatternFill("solid", fgColor="8C7A42")

        num_cols = {"Sold Qty", "Total Qty", "Net Revenue", "Inv Stock", "Inv (WIP)", "Blocked Qty"}
        for r in rows:
            if kind == "pivot":
                line = [r.get("customer", ""), r.get("sku", ""), r.get("qty", 0)]
                if show_rev:
                    line.append(r.get("revenue", 0))
                line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("image_url", "") or ""]
            else:
                line = [r.get("date", ""), r.get("sku", ""), r.get("customer", ""), r.get("type", ""), r.get("qty", 0)]
                if show_rev:
                    line.append(r.get("revenue", 0))
                line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("blocked_qty", 0), r.get("image_url", "") or ""]
            ws.append(line)

        for col_idx, h in enumerate(headers, start=1):
            if h in num_cols:
                for row_i in range(2, ws.max_row + 1):
                    ws.cell(row=row_i, column=col_idx).number_format = _OVERALL_NUM_FMT

        for col_cells in ws.columns:
            length = max((len(str(c.value)) for c in col_cells if c.value is not None), default=10)
            ws.column_dimensions[col_cells[0].column_letter].width = min(max(length + 2, 10), 60)

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)
        safe_title = re.sub(r"[^A-Za-z0-9_-]+", "_", title)
        resp = app.response_class(
            bio.read(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        resp.headers["Content-Disposition"] = f"attachment; filename={safe_title}_{kind}.xlsx"
        return resp
    except Exception as e:
        return jsonify({"error": f"excel export failed: {e}"}), 500

@app.route("/api/overall_export/pdf", methods=["POST"])
def api_overall_export_pdf():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        try:
            from reportlab.lib import colors
            from reportlab.lib.pagesizes import A4, landscape
            from reportlab.lib.units import mm
            from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, Image as RLImage
            from reportlab.lib.styles import getSampleStyleSheet
        except ImportError:
            return jsonify({"error": "PDF export ke liye 'reportlab' package deploy me install nahi hai — "
                                      "requirements.txt me 'reportlab' add karke Railway par redeploy karein."}), 500
        from concurrent.futures import ThreadPoolExecutor, as_completed

        payload = request.get_json(force=True) or {}
        kind  = payload.get("kind", "transactions")
        rows  = payload.get("rows") or []
        title = payload.get("title") or "Overall Details"
        show_rev = bool(rows) and rows[0].get("revenue") is not None

        # ── Photos: sirf UNIQUE URLs download karo (Transactions me ek hi SKU
        #    baar baar aata hai), parallel me, chhota timeout, aur ek limit
        #    taaki bahut zyada rows ho to bhi PDF hang na ho / gunicorn
        #    timeout na maare. Limit se upar wale rows me photo blank rahega. ──
        MAX_PDF_IMAGES = 100
        IMG_TIMEOUT = 2.0

        def _download_thumb(url):
            try:
                ir = requests.get(url, timeout=IMG_TIMEOUT)
                ir.raise_for_status()
                raw = ir.content
                if PIL_AVAILABLE:
                    im = Image.open(io.BytesIO(raw)).convert("RGB")
                    im.thumbnail((90, 90))
                    out = io.BytesIO()
                    im.save(out, format="JPEG", quality=78)
                    out.seek(0)
                    return out.read()
                return raw
            except Exception:
                return None

        unique_urls = []
        seen = set()
        for r in rows:
            u = r.get("image_url")
            if u and u not in seen:
                seen.add(u)
                unique_urls.append(u)
            if len(unique_urls) >= MAX_PDF_IMAGES:
                break

        img_bytes_cache = {}
        if unique_urls:
            with ThreadPoolExecutor(max_workers=8) as ex:
                futs = {ex.submit(_download_thumb, u): u for u in unique_urls}
                for fut in as_completed(futs):
                    u = futs[fut]
                    try:
                        img_bytes_cache[u] = fut.result()
                    except Exception:
                        img_bytes_cache[u] = None

        def _img_flowable(url):
            raw = img_bytes_cache.get(url)
            if not raw:
                return ""
            try:
                return RLImage(io.BytesIO(raw), width=13 * mm, height=13 * mm)
            except Exception:
                return ""

        styles = getSampleStyleSheet()
        elements = [Paragraph(str(title).replace("_", " "), styles["Heading2"]), Spacer(1, 8)]
        if len(rows) > 1500:
            elements.append(Paragraph(f"({len(rows)} rows — showing all; photos limited to first "
                                       f"{MAX_PDF_IMAGES} unique SKUs for speed)", styles["Normal"]))
            elements.append(Spacer(1, 6))

        if kind == "pivot":
            headers = ["Photo", "Customer", "SKU", "Total Qty"] + (["Net Revenue"] if show_rev else []) \
                      + ["Stock", "WIP"]
        else:
            headers = ["Photo", "Date", "SKU", "Customer", "Type", "Qty"] + (["Net Revenue"] if show_rev else []) \
                      + ["Stock", "WIP", "Blocked"]

        table_data = [headers]
        for r in rows:
            img_cell = _img_flowable(r.get("image_url"))
            if kind == "pivot":
                line = [img_cell, r.get("customer", ""), r.get("sku", ""), r.get("qty", 0)]
                if show_rev:
                    line.append(r.get("revenue", 0))
                line += [r.get("inv_stock", 0), r.get("inv_wip", 0)]
            else:
                line = [img_cell, r.get("date", ""), r.get("sku", ""), r.get("customer", ""), r.get("type", ""), r.get("qty", 0)]
                if show_rev:
                    line.append(r.get("revenue", 0))
                line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("blocked_qty", 0)]
            table_data.append(line)

        tbl = Table(table_data, repeatRows=1)
        tbl.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#8C7A42")),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
            ("FONTSIZE", (0, 0), (-1, -1), 7),
            ("GRID", (0, 0), (-1, -1), 0.5, colors.grey),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F7F5EE")]),
        ]))
        elements.append(tbl)

        bio = io.BytesIO()
        doc = SimpleDocTemplate(bio, pagesize=landscape(A4), topMargin=18, bottomMargin=18, leftMargin=18, rightMargin=18)
        doc.build(elements)
        bio.seek(0)
        safe_title = re.sub(r"[^A-Za-z0-9_-]+", "_", str(title))
        resp = app.response_class(bio.read(), mimetype="application/pdf")
        resp.headers["Content-Disposition"] = f"attachment; filename={safe_title}_{kind}.pdf"
        return resp
    except Exception as e:
        return jsonify({"error": f"pdf export failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  💸 DISCOUNT LEAKAGE REPORT  (admin only)
#  MRP vs actual Selling Price ka gap. Jaha qty zyada × discount zyada,
#  wahan sabse zyada "leakage" (lost value).
# ════════════════════════════════════════════════════════════════
def _build_discount_leakage(min_disc=0.0, sort_key="leakage"):
    data = get_data()
    comp = data[0]
    rows = []
    tot_leak = 0.0
    tot_units = 0.0
    for it in comp:
        mrp = float(it.get("mrp") or 0)
        qty = float(it.get("final_qty") or 0)
        # Overall qty-weighted average SP (total_net_revenue/qty) — same method
        # ab item compile step mein bhi use hota hai (discount_pct), taaki
        # Discount Leakage aur baaki app mein number match kare.
        sp  = (float(it.get("total_net_revenue") or 0) / qty) if qty > 0 else 0.0
        if mrp <= 0 or sp <= 0 or qty <= 0:
            continue
        if sp >= mrp:        # koi discount nahi (ya MRP se upar) → skip
            continue
        disc_pct = round((mrp - sp) / mrp * 100, 1)
        if disc_pct < min_disc:
            continue
        per_unit_gap = mrp - sp
        leakage = per_unit_gap * qty          # total value "lost" vs MRP
        tot_leak += leakage
        tot_units += qty
        rows.append({
            "sku": it.get("sku"), "sku_name": it.get("sku_name", ""), "image_url": it.get("image_url", ""),
            "stone_color": it.get("stone_color", ""),
            "taxon": it.get("taxon", ""), "plating": it.get("plating", ""),
            "mrp": mrp, "avg_sp": round(float(it.get("avg_selling_price") or 0), 2),
            "last_sp": round(sp, 2), "disc_pct": disc_pct,
            "per_unit_gap": round(per_unit_gap, 2), "qty": int(round(qty)),
            "leakage": round(leakage, 2),
            "net_revenue": float(it.get("total_net_revenue") or 0),
        })
    key = {"leakage":"leakage","discount":"disc_pct","qty":"qty","revenue":"net_revenue"}.get(sort_key, "leakage")
    rows.sort(key=lambda x: x.get(key, 0), reverse=True)
    return {
        "rows": rows[:500],
        "total_leakage": round(tot_leak, 2),
        "total_units": int(round(tot_units)),
        "count": len(rows),
    }

@app.route("/api/discount-leakage")
def api_discount_leakage():
    if session.get("role") != "admin":
        return jsonify({"error": "admin only"}), 403
    try:
        md = float(request.args.get("min", "0") or 0)
    except Exception:
        md = 0.0
    sk = request.args.get("sort", "leakage").strip()
    try:
        return jsonify(_build_discount_leakage(md, sk))
    except Exception as e:
        return jsonify({"error": f"discount leakage build failed: {e}"}), 500

